       unwatchStrategy(input.slice('unwatch '.length));
       rl.prompt();
       return;
     }

     if (lower === 'sim') {
       console.log('Simulation: ' + (state.simulation ? 'on' : 'off'));
       rl.prompt();
       return;
     }

     if (lower === 'sim on') {
       state.simulation = true;
       console.log('Simulation on.');
       rl.prompt();
       return;
     }

     if (lower === 'sim off') {
       state.simulation = false;
       console.log('Simulation off.');
       rl.prompt();
       return;
     }

     if (lower === 'trade') {
       console.log('Trade mode: ' + (state.trade ? 'on' : 'off'));
       rl.prompt();
       return;
     }

     if (lower === 'trade on') {
       state.trade = true;
       console.log('Real trade mode on.');
       rl.prompt();
       return;
     }

     if (lower === 'trade off') {
       state.trade = false;
       console.log('Real trade mode off.');
       rl.prompt();
       return;
     }

     if (lower.startsWith('buy')) {
       const amount = input.slice(3).trim();
       await buy(amount || '0.01');
       rl.prompt();
       return;
     }

     if (lower.startsWith('sell')) {
