   if (!state.mint) {
     state.strategyStatus = 'waiting for mint';
     return;
   }

   if (!state.currentPrice || state.lastPrice === 0) {
     state.strategyStatus = 'waiting for price';
     return;
   }

   state.strategyStatus = 'running';
   const signal = evaluateSignal();
   if (!signal) return;

