 async function connectRealtime() {
   if (!state.apiKey) {
     console.log('Live stream disabled: missing PUMP_API_KEY in .env');
     return null;
   }

   let WebSocketCtor = globalThis.WebSocket;
   if (!WebSocketCtor) {
     try {
       const wsModule = await import('ws');
       WebSocketCtor = wsModule.WebSocket;
     } catch (error) {
       console.log('Node WebSocket support is unavailable; live stream disabled.');
       return null;
     }
   }

   const ws = new WebSocketCtor('wss://pumpportal.fun/api/data?api-key=' + encodeURIComponent(state.apiKey));
   ws.addEventListener('open', () => {
     state.liveStreamReady = true;
     state.strategyStatus = state.mint ? 'watching feed' : 'idle';
     console.log('Connected to PumpPortal realtime stream.');
     if (state.mint) {
       ws.send(JSON.stringify({ method: 'subscribeTokenTrade', keys: [state.mint] }));
     }
   });

   ws.addEventListener('message', async (event) => {
     try {
       const payload = JSON.parse(String(event.data));
       const price = extractPrice(payload);
       if (price) {
         state.lastPrice = Number(state.currentPrice) > 0 ? state.currentPrice : price;
         state.currentPrice = price;
         if (state.tickerEnabled) {
           renderTickerLine();
         }
         await maybeAutoTrade();
         renderStrategyTick();
       }
     } catch (error) {
       // Ignore parsing noise from the stream.
     }
   });

   ws.addEventListener('close', () => {
     state.liveStreamReady = false;
     state.strategyStatus = state.mint ? 'feed disconnected' : 'idle';
     console.log('PumpPortal stream closed.');
   });

   ws.addEventListener('error', (error) => {
     state.liveStreamReady = false;
     state.strategyStatus = state.mint ? 'feed error' : 'idle';
     console.log('PumpPortal stream error: ' + String(error.message || error));
   });

   state.websocket = ws;
   return ws;
 }

 async function commandLoop() {
   const rl = readline.createInterface({
     input: process.stdin,
     output: process.stdout,
     terminal: true,
   });

   state.rl = rl;
   if (state.statusTimer) clearInterval(state.statusTimer);
   state.statusTimer = setInterval(() => {
     if (!state.rl) return;
     if (typeof state.rl.line === 'string' && state.rl.line.length > 0) return;
     renderStatusBanner();
   }, 3000);

   rl.setPrompt('caterkiller> ');
   rl.prompt();

   rl.on('line', async (raw) => {
     const input = String(raw || '').trim();
     if (!input) {
       rl.prompt();
       return;
     }

     const lower = input.toLowerCase();

     if (lower === 'help') {
       printHelp();
       rl.prompt();
       return;
     }

     if (lower === 'exit' || lower === 'quit') {
       console.log('Closing Caterkiller.');
       rl.close();
       return;
     }

     if (lower === 'status') {
       showStatus();
       rl.prompt();
       return;
     }

     if (lower === 'balance') {
       await getWalletBalance();
       rl.prompt();
       return;
     }

     if (lower === 'mcap') {
       await getMarketCap();
       rl.prompt();
       return;
     }

     if (lower === 'ticker') {
       console.log('Ticker: ' + (state.tickerEnabled ? 'on' : 'off'));
       rl.prompt();
       return;
     }

     if (lower === 'ticker on') {
       setTicker(true);
       rl.prompt();
       return;
     }

     if (lower === 'ticker off') {
       setTicker(false);
       rl.prompt();
       return;
     }

     if (lower === 'price') {
       console.log('Current price: ' + formatCachedPrice());
       rl.prompt();
       return;
     }

     if (lower.startsWith('price ')) {
       const parsed = Number(input.slice('price '.length).trim());
       if (!Number.isFinite(parsed) || parsed <= 0) {
         console.log('Usage: price [SOL]');
       } else {
         state.lastPrice = Number(state.currentPrice) > 0 ? state.currentPrice : parsed;
         state.currentPrice = parsed;
         if (state.tickerEnabled) {
           renderTickerLine();
         }
         console.log('Price set to: ' + parsed.toFixed(6) + ' SOL');
       }
       rl.prompt();
       return;
     }

     if (lower === 'strategy') {
       showStrategy();
       rl.prompt();
       return;
     }

     if (lower.startsWith('strategy ')) {
       const name = input.slice('strategy '.length).trim();
       setStrategy(name);
       rl.prompt();
       return;
     }

     if (lower === 'start' || lower === 'watch') {
       console.log('Started: ' + (state.watchedStrategies.length ? state.watchedStrategies.join(', ') : '<none>'));
       rl.prompt();
       return;
     }

     if (lower.startsWith('start ') || lower.startsWith('watch ')) {
       startStrategy(input.slice(input.indexOf(' ') + 1).trim());
       rl.prompt();
       return;
     }

     if (lower === 'stop' || lower === 'unwatch') {
       console.log('Usage: stop [strategy]');
       rl.prompt();
       return;
     }

     if (lower.startsWith('stop ') || lower.startsWith('unwatch ')) {
       stopStrategy(input.slice(input.indexOf(' ') + 1).trim());
       rl.prompt();
       return;
     }

     if (lower === 'sim') {
       console.log('Simulation: ' + (state.simulation ? 'on' : 'off'));
       rl.prompt();
       return;
     }

     if (lower === 'sim on') {
       state.simulation = true;
       console.log('Simulation on.');
       rl.prompt();
       return;
     }

     if (lower === 'sim off') {
       state.simulation = false;
       console.log('Simulation off.');
       rl.prompt();
       return;
     }

     if (lower === 'trade') {
       console.log('Trade mode: ' + (state.trade ? 'on' : 'off'));
       rl.prompt();
       return;
     }

     if (lower === 'trade on') {
       state.trade = true;
       console.log('Real trade mode on.');
       rl.prompt();
       return;
     }

     if (lower === 'trade off') {
       state.trade = false;
       console.log('Real trade mode off.');
       rl.prompt();
       return;
     }

     if (lower.startsWith('buy')) {
       const amount = input.slice(3).trim();
       await buy(amount || '0.01');
       rl.prompt();
       return;
     }

     if (lower.startsWith('sell')) {
       const percent = input.slice(4).trim();
       await sell(percent || 100);
       rl.prompt();
       return;
     }

     if (isMintLike(input)) {
       state.mint = input.trim();
       if (state.websocket) {
         state.websocket.send(JSON.stringify({ method: 'subscribeTokenTrade', keys: [state.mint] }));
       }
       console.log('Current mint set to: ' + state.mint);
       rl.prompt();
       return;
     }

     if (lower.startsWith('mint ')) {
       state.mint = input.slice(4).trim();
       console.log('Current mint set to: ' + state.mint);
       rl.prompt();
       return;
     }

     console.log('Unknown command. Type "help" for commands.');
     rl.prompt();
   });

   rl.on('close', () => {
     if (state.statusTimer) {
       clearInterval(state.statusTimer);
       state.statusTimer = null;
     }
     process.exit(0);
   });
 }

