   const now = Date.now();
   if (state.lastSignalAt && now - state.lastSignalAt < state.strategyCooldownMs) {
     return null;
   }

   if (state.strategy === 'momentum') {
     if (score >= 0.5) {
       state.lastSignalAt = now;
