   state.strategy = key;
   state.botRunning = true;
   if (state.strategy === 'dca') {
     state.dcaLastBuyAt = 0;
   }
   if (state.rl) {
     resetPromptPrefix();
   }
   logSuccess('Bot started.');
 }

